import React, { useContext, useState, useEffect } from 'react';
import { AppContext } from './AppContext';
import './SettingsPanel.css';
import backgroundImage from '../assets/background.jpg'; // New background

export default function SettingsPanel() {
  const { user, theme, setTheme, language, setLanguage, token, setUser } = useContext(AppContext);

  const [name, setName] = useState(user?.full_name || '');
  const [age, setAge] = useState(user?.age || '');
  const [gender, setGender] = useState(user?.gender || '');
  const [message, setMessage] = useState(null);

  useEffect(() => {
    setName(user?.full_name || '');
    setAge(user?.age || '');
    setGender(user?.gender || '');
  }, [user]);

  const toggleTheme = () => {
    setTheme(theme === 'dark' ? 'light' : 'dark');
  };

  const handleLanguageChange = (e) => {
    setLanguage(e.target.value);
  };

  const handleSave = async () => {
    setMessage(null);
    try {
      const res = await fetch('/user/update', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          full_name: name,
          age,
          gender,
          email: user.email,
        }),
      });
      if (!res.ok) throw new Error('Update failed');
      const updatedUser = await res.json();
      setUser(updatedUser);
      setMessage('User info updated!');
    } catch (e) {
      setMessage('Update failed.');
    }
  };

  return (
    <div
      className={`settings-page ${theme === 'dark' ? 'dark' : 'light'}`}
      style={{ backgroundImage: `url(${backgroundImage})` }}
    >
      <div className="settings-card">
        <h2>Settings</h2>

        <div className="setting-group">
          <label>Name</label>
          <input value={name} onChange={(e) => setName(e.target.value)} />
        </div>

        <div className="setting-group">
          <label>Age</label>
          <input
            type="number"
            min="1"
            max="120"
            value={age}
            onChange={(e) => setAge(e.target.value)}
          />
        </div>

        <div className="setting-group">
          <label>Gender</label>
          <select value={gender} onChange={(e) => setGender(e.target.value)}>
            <option value="">Select gender</option>
            <option value="male">Male</option>
            <option value="female">Female</option>
            <option value="other">Other</option>
          </select>
        </div>

        <div className="setting-group">
          <label>Theme</label>
          <button onClick={toggleTheme}>
            Switch to {theme === 'dark' ? 'Light' : 'Dark'} Mode
          </button>
        </div>

        <div className="setting-group">
          <label>Language</label>
          <select value={language} onChange={handleLanguageChange}>
            <option value="en">English</option>
            <option value="fr">French</option>
            <option value="ar">Arabic</option>
          </select>
        </div>

        <button className="save-button" onClick={handleSave}>Save Settings</button>
        {message && <p className="message">{message}</p>}
      </div>
    </div>
  );
}
